#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <utility>
#include <vector>
using namespace std;

static string expected(int n, const vector<int>& codes) {
    vector<bool> arrive(n, false);
    for (size_t i = 0; i < codes.size(); ++i) arrive[codes[i]] = true;
    bool all = true;
    for (int i = 0; i < n; ++i) if (!arrive[i]) { all = false; break; }
    ostringstream os;
    if (all) { os << n; return os.str(); }
    bool first = true;
    for (int i = 0; i < n; ++i) if (!arrive[i]) {
        if (!first) os << ' ';
        os << i;
        first = false;
    }
    return os.str();
}

static bool check(const string& exe, int n, const vector<int>& codes, int id) {
    const string inFile = "l3a06p1_input.txt", outFile = "l3a06p1_output.txt";
    {
        ofstream out(inFile);
        out << n << ' ' << codes.size() << '\n';
        for (size_t i = 0; i < codes.size(); ++i)
            out << codes[i] << (i + 1 == codes.size() ? '\n' : ' ');
    }
    const string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string actual((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    vector<int> got, want;
    {
        istringstream p(actual); int v; while (p >> v) got.push_back(v);
    }
    {
        istringstream p(expected(n, codes)); int v; while (p >> v) want.push_back(v);
    }
    bool ok = code == 0 && got == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << n << " m=" << codes.size()
             << ", expected=" << expected(n, codes)
             << ", actual=" << actual.substr(0, 120) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<pair<int, vector<int>>> tests;
    tests.push_back(make_pair(3, vector<int>{0, 2, 1}));
    tests.push_back(make_pair(3, vector<int>{0, 0, 0, 0, 0}));
    tests.push_back(make_pair(2, vector<int>{0, 1}));
    tests.push_back(make_pair(2, vector<int>{1, 1, 1}));
    tests.push_back(make_pair(5, vector<int>{4, 3, 2, 1, 0}));
    tests.push_back(make_pair(1000, vector<int>(1000, 0)));
    {
        vector<int> c(1000);
        for (int i = 0; i < 1000; ++i) c[i] = i;
        tests.push_back(make_pair(1000, c));
    }
    {
        vector<int> c(2); c[0] = 0; c[1] = 999;
        tests.push_back(make_pair(1000, c));
    }
    unsigned seed = 202306u;
    for (int trial = 0; trial < 8; ++trial) {
        seed = seed * 1664525u + 1013904223u;
        int n = 2 + static_cast<int>(seed % 999u);
        seed = seed * 1664525u + 1013904223u;
        int m = 2 + static_cast<int>(seed % 999u);
        vector<int> c(m);
        for (int i = 0; i < m; ++i) {
            seed = seed * 1664525u + 1013904223u;
            c[i] = static_cast<int>(seed % static_cast<unsigned>(n));
        }
        tests.push_back(make_pair(n, c));
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i].first, tests[i].second, static_cast<int>(i + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

