#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>
using namespace std;

static bool okPwd(const string& s) {
    int l = static_cast<int>(s.size());
    if (l < 6 || l > 12) return false;
    bool hasC = false, hasL = false, hasD = false, hasS = false;
    for (size_t i = 0; i < s.size(); ++i) {
        char ch = s[i];
        if (ch >= 'A' && ch <= 'Z') hasC = true;
        else if (ch >= 'a' && ch <= 'z') hasL = true;
        else if (ch >= '0' && ch <= '9') hasD = true;
        else if (ch == '!' || ch == '@' || ch == '#' || ch == '$') hasS = true;
        else return false;
    }
    if (!hasS) return false;
    if (static_cast<int>(hasC) + static_cast<int>(hasL) + static_cast<int>(hasD) < 2) return false;
    return true;
}

static string expected(const string& line) {
    string out;
    size_t start = 0;
    while (true) {
        size_t pos = line.find(',', start);
        string seg = (pos == string::npos) ? line.substr(start) : line.substr(start, pos - start);
        if (okPwd(seg)) out += seg + "\n";
        if (pos == string::npos) break;
        start = pos + 1;
    }
    return out;
}

static string show(const string& s) {
    string result;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\n') result += "\\n";
        else result += s[i];
        if (result.size() > 125) { result += "..."; break; }
    }
    return result;
}

static bool check(const string& exe, const string& input, int id) {
    const string inFile = "l3a06p2_input.txt", outFile = "l3a06p2_output.txt";
    { ofstream out(inFile, ios::binary); out << input << '\n'; }
    const string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile, ios::binary);
    string actual((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    for (size_t i = 0; i + 1 < actual.size(); ++i)
        if (actual[i] == '\r' && actual[i + 1] == '\n') actual.erase(i, 1);
    if (!actual.empty() && actual.back() == '\n') actual.pop_back();
    string want = expected(input);
    if (!want.empty() && want.back() == '\n') want.pop_back();
    bool ok = code == 0 && actual == want;
    if (!ok) cout << "[FAIL] case " << id << ": input=" << show(input)
                  << " expected=" << show(want) << " actual=" << show(actual)
                  << ", process status=" << code << '\n';
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<string> tests = {
        "seHJ12!@,sjdkffH$123,sdf!@&12HDHa!,123&^YUhg@!",
        "aA1!@#",
        "aA1!@",
        "aA1!@#bbbbbb",
        "aA1!@#bbbbbbb",
        "aaaaa!",
        "aaaaA!",
        "aaaaA1",
        "aaaaA1*",
        "AAAA1!@#",
        "aA1!@#,,aA1!@#",
        "aA1!@#,aA1!@#,aA1!@#",
        "zzZZ99$$",
        "zzZZ99$$zzZZ99$",
        "01234!@#ABC",
        "!@#!@#!@#",
        "aA1!@#,",
        "GESP66!@,gesp66!@,Ge66!@"
    };
    unsigned seed = 202306u;
    const string alphabet = "aB3!@#^&*zZ9$,";
    for (int trial = 0; trial < 10; ++trial) {
        string s;
        int len = 20 + trial * 9;
        for (int i = 0; i < len; ++i) {
            seed = seed * 1664525u + 1013904223u;
            s += alphabet[seed % alphabet.size()];
        }
        tests.push_back(s);
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}
